param([string]$BaseUrl='http://127.0.0.1:18091',[string]$Label='baseline',[int]$Iterations=20,[int]$Warmups=3,[string[]]$OnlyQueries=@('match_page','top_scorers','standings'))
$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.Net.Http
$queries=[ordered]@{match_page='/api/match/list?page=1&size=10';top_scorers='/api/statistics/top-scorers';standings='/api/statistics/standings'}
$client=[System.Net.Http.HttpClient]::new();$client.Timeout=[TimeSpan]::FromSeconds(60);$records=[System.Collections.Generic.List[object]]::new();$errors=0;$raw=Join-Path $PSScriptRoot "api_${Label}_raw.txt";Set-Content $raw '' -Encoding UTF8
try { foreach($name in $OnlyQueries){if(!$queries.Contains($name)){throw "Unknown API query: $name"};for($n=1;$n -le ($Warmups+$Iterations);$n++){$url=$BaseUrl+$queries[$name];$sw=[Diagnostics.Stopwatch]::StartNew();$response=$client.GetAsync($url).GetAwaiter().GetResult();$bytes=$response.Content.ReadAsByteArrayAsync().GetAwaiter().GetResult();$sw.Stop();$code=[int]$response.StatusCode;$body=[Text.Encoding]::UTF8.GetString($bytes);$json=$body|ConvertFrom-Json;$count=if($name -eq 'match_page'){$json.data.records.Count}else{$json.data.Count};$success=($code -eq 200 -and $json.code -eq 0);if(!$success){$errors++};Add-Content $raw "label=$Label query=$name sample=$n warmup=$($n -le $Warmups) status=$code app_code=$($json.code) rows=$count bytes=$($bytes.Length) client_total_ms=$([Math]::Round($sw.Elapsed.TotalMilliseconds,3))" -Encoding UTF8;if($n -gt $Warmups){$records.Add([pscustomobject]@{label=$Label;query=$name;sample=$n-$Warmups;http_status=$code;app_code=$json.code;rows=$count;response_bytes=$bytes.Length;client_total_ms=[Math]::Round($sw.Elapsed.TotalMilliseconds,3);error=(!$success)})}}}}
finally{$client.Dispose()}
$csv=Join-Path $PSScriptRoot "api_${Label}_samples.csv";$records|Export-Csv -NoTypeInformation -Encoding UTF8 $csv;$summary=[System.Collections.Generic.List[object]]::new();foreach($g in ($records|Group-Object query)){$values=@($g.Group|ForEach-Object {$_.client_total_ms}|Sort-Object);$n=$values.Count;$median=if($n%2){$values[[int][Math]::Floor($n/2)]}else{($values[$n/2-1]+$values[$n/2])/2};$p95=$values[[Math]::Ceiling(.95*$n)-1];$summary.Add([pscustomobject]@{label=$Label;query=$g.Name;samples=$n;median_client_ms=[Math]::Round($median,3);p95_nearest_rank_client_ms=[Math]::Round($p95,3);min_ms=[Math]::Round($values[0],3);max_ms=[Math]::Round($values[-1],3);errors=($g.Group|Where-Object error).Count;rows=($g.Group|Select-Object -Last 1).rows;response_bytes=($g.Group|Select-Object -Last 1).response_bytes})};$summary|Export-Csv -NoTypeInformation -Encoding UTF8 (Join-Path $PSScriptRoot "api_${Label}_summary.csv");$summary|Format-Table -AutoSize;"total_errors=$errors";if($errors){throw 'HTTP API returned non-success responses'}
